	/**
	 * Tope de BYTES serializados por petición. Por defecto 3 MiB.
	 *
	 * El tope por número de filas no basta: api-db-go corre sobre Fiber, cuyo
	 * `BodyLimit` acota el cuerpo de la petición, y 500 mensajes ricos (embeds
	 * llenos, 10 adjuntos) se van a ~18 MiB. El servidor contestaba 413, el
	 * reintento fallaba igual y el lote ENTERO se descartaba — 500 mensajes
	 * perdidos, en silencio salvo por un log de error.
	 *
	 * 3 MiB deja margen holgado bajo el límite del servidor para cabeceras y para
	 * la diferencia entre esta estimación y el JSON final.
	 */
	maxBatchBytes?: number;
	/**
	 * Tope duro de filas en memoria. Si api-db está caído, sin este tope el
	 * buffer crecería hasta agotar el heap del worker y tumbar el bot por un
	 * fallo de un servicio auxiliar. Al llegar al tope se descartan las filas
	 * NUEVAS y se cuentan en `droppedMessages`. Por defecto 20.000 filas
	 * (~40 s de margen a 500 msg/s).
	 */
	maxBufferedMessages?: number;
	/** Mismo tope para los ids pendientes de marcar como borrados. */
	maxBufferedDeletes?: number;
}

// `type` y no `interface` a propósito: los alias de tipo obtienen firma de
// índice implícita, así que un `MessageIngestStats` se puede pasar donde se
// espera `Record<string, unknown>` — que es exactamente lo que pide el `meta`
// del logger. Una interface no lo permitiría.
export type MessageIngestStats = {
	/** Filas aceptadas por el buffer desde el arranque. */
	enqueued: number;
	/** Filas confirmadas por api-db. */
	flushed: number;
	/** Filas descartadas por tope de buffer o por fallo tras reintento. */
	droppedMessages: number;
	/** Ids de borrado descartados por tope de buffer o por fallo tras reintento. */
	droppedDeletes: number;
	/** Lotes que fallaron (incluye los que luego el reintento salvó). */
	failedBatches: number;
	/** Filas esperando ahora mismo. */
	pendingMessages: number;
	/** Ids de borrado esperando ahora mismo. */
	pendingDeletes: number;
	/** Filas que el servidor rechazó una a una sin tumbar su lote. */
	rejectedMessages: number;
	/** Filas descartadas aquí por no caber ellas solas en `maxBatchBytes`. */
	oversizedMessages: number;
};

const DEFAULTS = {
	enabled: true,
	flushIntervalMs: 500,
	maxBatchSize: 500,
	maxBatchBytes: 3 * 1024 * 1024,
	maxBufferedMessages: 20_000,
	maxBufferedDeletes: 20_000
} as const;

export class MessageIngestBuffer {
	private readonly transport: MessageIngestTransport;
	private readonly logger: MessageIngestLogger;
	private readonly options: Required<MessageIngestBufferOptions>;

	/** Map en vez de array: coalesce por id y conserva el orden de inserción. */
	private readonly pending = new Map<string, MessageStoreWrite>();
	private readonly pendingDeletes = new Set<string>();

	private timer: NodeJS.Timeout | null = null;
	private flushing = false;
	private stopped = false;

	private stats = {
		enqueued: 0,
		flushed: 0,
		droppedMessages: 0,
		droppedDeletes: 0,
		failedBatches: 0,
		rejectedMessages: 0,
		oversizedMessages: 0
	};

	constructor(
		transport: MessageIngestTransport,
		logger: MessageIngestLogger,
		options: MessageIngestBufferOptions = {}
	) {
		this.transport = transport;
		this.logger = logger;
		this.options = { ...DEFAULTS, ...options };
	}

	start(): void {
		if (this.timer || !this.options.enabled) return;
		this.stopped = false;
		this.timer = setInterval(() => {
			void this.flush();
		}, this.options.flushIntervalMs);
		// El intervalo no debe mantener vivo el event loop: si todo lo demás
		// terminó, el proceso tiene que poder salir.
		this.timer.unref?.();
	}

	/**
	 * Encola un mensaje. Nunca lanza ni espera: los handlers del gateway están
	 * en la ruta caliente y no pueden bloquearse por el store.
	 */
	add(row: MessageStoreWrite): void {
		if (!this.options.enabled || this.stopped) return;

		const existing = this.pending.get(row.id);
		if (existing) {
			// Fusión sobre lo pendiente en lugar de reemplazo: los payloads de
			// MESSAGE_UPDATE son parciales por contrato, así que un reemplazo
			// directo perdería campos que solo traía el MESSAGE_CREATE.
			this.pending.set(row.id, mergeRow(existing, row));
			return;
		}

		if (this.pending.size >= this.options.maxBufferedMessages) {
			this.stats.droppedMessages++;
			return;
		}

		this.pending.set(row.id, row);
		this.stats.enqueued++;

		// Volcado anticipado por tamaño: sin esto, una ráfaga por encima de
		// `maxBatchSize` esperaría igualmente al tick y el lote crecería sin
		// control entre ticks.
		if (this.pending.size >= this.options.maxBatchSize) void this.flush();
	}

	/**
	 * Devuelve la fila que sigue esperando en el buffer, si la hay.
	 *
	 * Cubre la ventana ciega entre escribir un mensaje y que llegue a Postgres
	 * (como mucho `flushIntervalMs`). Sin esto, editar o borrar un mensaje
