	 * el evento saldría sin cuerpo previo. Es una lectura de un Map en memoria:
	 * ni round-trip ni coste apreciable.
	 */
	peek(id: string): MessageStoreWrite | undefined {
		return this.pending.get(id);
	}

	/** Encola el marcado de borrado de uno o varios mensajes. */
