14	 *
15	 * The OLD code in InteractionGrpcService.forwardDeferWithBudget set up a
16	 * tracker with a tight budget. If the worker's POST to Discord finished
17	 * JUST after the tracker's timer fired:
18	 *   1. The tracker rejects with "Request X timed out after Yms".
19	 *   2. The worker's success response lands in
20	 *      `RequestTracker.resolveRequest`, which finds no pending entry and
21	 *      logs "Received response for unknown request" — response is lost.
22	 *   3. The SDK receives `DEFER_TIMEOUT` and sets `deferFailed = true`, so
23	 *      every subsequent editReply/followUp is auto-suppressed.
24	 *   4. Meanwhile Discord DID receive the ACK and the followup webhook
25	 *      works fine.
26	 *
27	 * The fix: a late-arriving SUCCESS response should override a
28	 * tracker-timeout-induced DEFER_TIMEOUT. The cost of getting this wrong
29	 * (a deferred-but-not-replied interaction that lingers) is much smaller
30	 * than the cost of the bug (a fully-working interaction the user can't
31	 * see updates for).
32	 *
33	 * Tests below pin the contract:
34	 *   - `RequestTracker.resolveRequest` for a settled request that returned
35	 *     success should be observable (via a "late success" hook) so the
36	 *     caller can convert the timeout into a success.
37	 *   - The hook must NOT fire for failure responses — a real timeout
38	 *     masking a worker-reported failure would let a broken defer slip
39	 *     through.
40	 */
41	
42	describe("audit 1.6 — late success response overrides DEFER_TIMEOUT", () => {
43		let tracker: RequestTracker;
44		let onSettleSpy: ReturnType<typeof vi.fn>;
45	
46		beforeEach(() => {
47			vi.useFakeTimers();
48			tracker = new RequestTracker(30000);
49			onSettleSpy = vi.fn();
50			tracker.setOnSettle(onSettleSpy);
51		});
52	
53		afterEach(() => {
54			vi.useRealTimers();
55		});
56	
57		it("a success response arriving AFTER the tracker timed out is preserved as a 'late success'", async () => {
58			// 1. Track a request with a tiny budget.
59			const promise = tracker.trackRequest("trace-1", 100);
60			// 2. Fire the timeout.
61			vi.advanceTimersByTime(150);
62			// The promise should now have rejected.
63			await expect(promise).rejects.toThrow(/timed out/);
64			expect(onSettleSpy).toHaveBeenCalledWith("trace-1");
65	
66			// 3. Simulate the worker response arriving late with success=true.
67			// The audit says: this response used to be dropped with "Received
68			// response for unknown request". The fix must let the caller
69			// observe it (so the SDK doesn't set deferFailed=true on a defer
70			// that actually succeeded).
71			const lateResponse: MessageResponseIPC = {
72				success: true,
73				data: { ok: true },
74				timestamp: new Date().toISOString(),
75				request_id: "trace-1",
76				status: "OK" as any
77			} as any;
