import os from "node:os";
import * as grpc from "@grpc/grpc-js";
import {
	GrpcCoreChannelClient,
	type GrpcCoreRequest,
	type GrpcCoreResponse,
	GrpcRegistryClient,
	type GrpcRegistryMetrics,
	KenaCoreError,
	ResponseBuilder,
	reportError,
	setPubsubReady
} from "@kena/shared";
import { ChannelGrpcService } from "../../cluster/master/grpc/ChannelGrpcService.js";
import { ClientGrpcService } from "../../cluster/master/grpc/ClientGrpcService.js";
import { ClusterGrpcService } from "../../cluster/master/grpc/ClusterGrpcService.js";
import { GuildGrpcService } from "../../cluster/master/grpc/GuildGrpcService.js";
import { RoleGrpcService } from "../../cluster/master/grpc/RoleGrpcService.js";
import { InteractionGrpcService } from "../../cluster/master/grpc/services/InteractionGrpcService.js";
import { MemberGrpcService } from "../../cluster/master/grpc/services/MemberGrpcService.js";
import { MessageGrpcService } from "../../cluster/master/grpc/services/MessageGrpcService.js";
import { SlashCommandGrpcService } from "../../cluster/master/grpc/services/SlashCommandGrpcService.js";
import { ThreadGrpcService } from "../../cluster/master/grpc/services/ThreadGrpcService.js";
import { UserGrpcService } from "../../cluster/master/grpc/UserGrpcService.js";
import { VoiceGrpcService } from "../../cluster/master/grpc/VoiceGrpcService.js";
import type ClusterManager from "../../cluster/master/ClusterManager.js";
import type ClusterIPC from "../../cluster/master/ipc/ClusterIPC.js";
import { pendingRequestsSnapshot } from "../../cluster/master/ipc/RequestTracker.js";
import { CommandsStore } from "../../cluster/master/stores/commands/CommandsStore.js";
import { GrpcRateLimiter } from "../../infrastructure/grpc/middleware/GrpcRateLimiter.js";
import { getBotAllowedModules } from "../redis.js";
import { env } from "../../shared/Env.js";
import { LogType, logger } from "../../shared/Logger.js";

// Cuánto tiene que aguantar un work-channel abierto antes de considerarlo sano
// y reiniciar el contador de backoff. Ver el comentario en `openWorkChannel`.
const STREAM_STABLE_MS = 30_000;

// Deadline del `registerCore`. Es la única RPC del enlace que no lo tenía, y es
// justo la que sostiene todo el ciclo de reconexión: tras `teardownStream()` no
// queda ningún timer ni stream vivo, así que si su callback no vuelve JAMÁS el
// core se queda mudo para siempre. El keepalive del canal (30s/10s) no cubre el
// caso de un socket sano con el handler colgado al otro lado.
const REGISTER_CORE_DEADLINE_MS = 10_000;

function getMetrics(): GrpcRegistryMetrics {
	const mem = process.memoryUsage();
	return {
		memory_mb: Math.round(mem.rss / 1024 / 1024),
		cpu_percent: 0,
		grpc_rpm: 0,
		startup_time_ms: Math.round(process.uptime() * 1000),
		cpu_cores: os.cpus().length
	};
}

type ServiceHandler = (request: any) => Promise<any>;

function adaptImpl(impl: Record<string, (call: any, cb: any) => void>): Record<string, ServiceHandler> {
	const adapted: Record<string, ServiceHandler> = {};
	for (const [method, handler] of Object.entries(impl)) {
		adapted[method] = (request) =>
			new Promise((resolve, reject) => {
				handler({ request }, (err: any, result: any) => {
					if (err) reject(err);
					else resolve(result);
				});
			});
	}
	return adapted;
}

export async function startGatewayClient(
	clusterIPC: ClusterIPC,
	totalShards: number,
	// El servicio de reinicio necesita el manager, no sólo el IPC: `restartCluster`
	// (con su backoff de crash-loop y su guarda de reentrada) vive ahí.
	clusterManager: ClusterManager
): Promise<void> {
	// Circuit breakers: limits at 3x observed peak (100 req/s) over a 10s window.
	// These fire only on runaway modules, not on normal traffic spikes.
	//
	// El de TASA no basta, y el incidente del 11-08-2026 lo demostró: los ~115 req/s
	// que dejaron el core a 154 % de CPU y 10 GB quedaron muy por debajo de estos
	// 300/s, así que nunca se activó. Lo que tumbó al core fue la ACUMULACIÓN —con
	// 5 s de deadline y un core que ya no contestaba, del orden de 575 peticiones
	// vivas a la vez—, no el ritmo de entrada. De ahí el techo de concurrencia.
	//
	// 256 en vuelo por módulo: en tráfico sano son UNIDADES (entran a ~100/s y se
	// resuelven en decenas de ms), así que 256 es dos órdenes de magnitud de margen
	// y jamás toca a un módulo que funciona; y está por debajo de lo que produjo el
	// incidente, así que sí corta al desbocado. La línea de carga del minuto publica
	// el pico real (`inFlightPeak`) para poder ajustarlo con datos en vez de a ojo.
	const MAX_IN_FLIGHT_PER_MODULE = 256;

	const defaultRateLimiter = new GrpcRateLimiter({
		moduleRule: { maxRequests: 3_000, windowMs: 10_000 },
		maxInFlightPerModule: MAX_IN_FLIGHT_PER_MODULE,
		rpcRules: {
			// Identidad GLOBAL del bot (el usuario, no un member de servidor).
			// Discord de verdad sólo permite un puñado de cambios de username por
			// hora y aleatoriza el discriminador si detecta abuso — si Discord
			// nos corta aquí no es un 429 reintentable cualquiera, es una
			// penalización sobre la cuenta del bot. Por eso esta regla es, con
			// diferencia, la más estricta de las de identidad: más restrictiva
			// que editCurrentGuildMember (10/60s ≈ 600/h) y que
			// editCurrentApplication, que no cargan ese riesgo del lado Discord.
			"client.editCurrentUser": { maxRequests: 2, windowMs: 3_600_000 },
			// A diferencia del resto de RPCs bajo este limiter genérico, Discord
			// limita de verdad el PATCH de members/@me por servidor y el payload
			// puede llevar avatar+banner en base64 (varios MB por request): un
			// límite bajo y de ventana larga evita que un módulo en bucle sature
			// Discord o reviente la memoria del proceso con PATCHes de imágenes.
			"client.editCurrentGuildMember": { maxRequests: 10, windowMs: 60_000 },
			// La bio de la aplicación (PATCH /applications/@me, sólo texto) no
			// tiene un límite tan agresivo por parte de Discord como el
			// username, pero sigue siendo identidad pública del bot — se le da
			// la misma cadencia que a editCurrentGuildMember por consistencia.
			"client.editCurrentApplication": { maxRequests: 10, windowMs: 60_000 },
			// FetchCurrentApplication es una LECTURA (GET /applications/@me vía
			// applications.getCurrent()): a diferencia de las tres reglas de
			// arriba no escribe nada y no arriesga ninguna penalización de
			// Discord sobre la cuenta del bot, así que no necesita una ventana
			// larga y estricta — sólo un tope que amortigüe un módulo en bucle.
			// 600/60s es un orden de magnitud más permisivo que
			// editCurrentGuildMember/editCurrentApplication (10/60s) y sigue
			// muy por debajo del circuit breaker por módulo (moduleRule,
			// 3 000/10s) de arriba, que ya cubriría cualquier abuso real.
			"client.fetchCurrentApplication": { maxRequests: 600, windowMs: 60_000 }
		}
	});
	const interactionRateLimiter = new GrpcRateLimiter({
		moduleRule: { maxRequests: 3_000, windowMs: 10_000 },
		// Mismo techo de concurrencia: las interacciones son las que peor llevan la
		// espera —la ventana de ack de Discord se agota en 3 s— así que un rechazo
		// inmediato es mejor que una cola que nadie va a atender a tiempo.
		maxInFlightPerModule: MAX_IN_FLIGHT_PER_MODULE,
		rpcRules: {
			"interaction.replyToInteraction": { maxRequests: 1_500, windowMs: 10_000 },
			"interaction.followUpInteraction": { maxRequests: 1_500, windowMs: 10_000 }
		}
	});

	const messageService = new MessageGrpcService(clusterIPC, totalShards, 70_000, defaultRateLimiter);
	const userService = new UserGrpcService(clusterIPC, 30_000, defaultRateLimiter);
	// 10s (not 30s) so a wedged worker fails the interaction fast — Discord's
	// own ack window is gone long before 30s, and the long timeout produced
	// the "timed out after 30000ms" storm under a stuck worker.
	const interactionService = new InteractionGrpcService(clusterIPC, 10_000, interactionRateLimiter);
	const memberService = new MemberGrpcService(clusterIPC, totalShards, 30_000, defaultRateLimiter);
	const guildService = new GuildGrpcService(clusterIPC, totalShards, 30_000, defaultRateLimiter);
	const channelService = new ChannelGrpcService(clusterIPC, totalShards, 30_000, defaultRateLimiter);
	const threadService = new ThreadGrpcService(clusterIPC, totalShards, 30_000, defaultRateLimiter);
	const roleService = new RoleGrpcService(clusterIPC, totalShards, 30_000, defaultRateLimiter);
	const clientService = new ClientGrpcService(clusterIPC, 30_000, defaultRateLimiter);
	const voiceService = new VoiceGrpcService(clusterIPC, totalShards, 30_000, defaultRateLimiter);
	const clusterService = new ClusterGrpcService(clusterIPC, clusterManager);
	// Master-side pubsub gate. The worker has its own gate it flips only
	// after the Discord shard boot storm has settled — that's the BotWorker
	// optimisation for GUILD_CREATE flooding. The master never receives that
	// storm (it only forwards gRPCs and IPC), so its gate has no value to
	// add and would only silence operational publishes (player.reconnect)
	// that arrive here.
	setPubsubReady(true);
	// Awaited start: the ack listener subscribes asynchronously to a Redis
	// pubsub channel. If we let `bindAsync` accept gRPC traffic before the
	// subscribe handshake (~5-50ms) finishes, the first module ACK published
	// to `PLAYER_COMMAND_ACK_CHANNEL` lands with no listener attached — the
	// trace_id never resolves and the caller burns the full 30s timeout on
	// the very first `reconnectPlayer` after boot. Awaiting here means the
	// listener is guaranteed live before any handler in the map below can
	// fire.
	try {
		await voiceService.startAckListener();
	} catch (err) {
		logger.error(LogType.GRPC, "Failed to start player-ack listener", err);
	}

	// Barrido periódico de cubos del rate limiter, y —lo que de verdad importaba—
	// la ÚNICA señal proactiva que tiene el core sobre su propia carga.
	//
	// Antes de esto, un módulo con un bug podía llevar al core a 154 % de CPU y
	// 10 GB sin que nada lo dijera: `HealthLogger` y el log por petición están
	// detrás de `LOG_LEVEL=debug` (apagado en producción), las cuentas del rate
	// limiter no las leía nadie y `getPendingCount()` no se llamaba desde ningún
	// sitio. La primera noticia fue un usuario diciendo «no funciona».
	//
	// Va a `info` y una vez por minuto a propósito: es una línea por minuto, no un
	// volcado por petición, así que se puede dejar encendida en producción — que es
	// el único sitio donde sirve de algo.
	setInterval(() => {
		const swept = defaultRateLimiter.sweepStaleBuckets() + interactionRateLimiter.sweepStaleBuckets();
		if (swept > 0) {
			logger.debug(LogType.GRPC, `[RateLimiter] swept ${swept} stale bucket(s)`);
		}

		const general = defaultRateLimiter.drainMetrics();
		const interactions = interactionRateLimiter.drainMetrics();
		const inFlight = pendingRequestsSnapshot();
		const allowed = general.allowed + interactions.allowed;
		const blocked = general.blocked + interactions.blocked;
		// Pico de CONCURRENCIA por módulo y rechazos por el techo. Es el número con el
		// que se calibra `MAX_IN_FLIGHT_PER_MODULE`: si en semanas nunca pasa de dos
		// dígitos, el techo de 256 sobra; si se acerca, hay que mirar qué módulo.
		const concurrencyPeak = Math.max(general.inFlightPeak, interactions.inFlightPeak);
		const concurrencyRejected = general.inFlightRejected + interactions.inFlightRejected;

		// Silencio absoluto en un core en reposo: sin tráfico y sin nada en vuelo no
		// hay nada que contar, y una línea por minuto de ceros sólo enseña a la
		// gente a ignorar este log.
		if (allowed === 0 && blocked === 0 && inFlight.total === 0) return;

		const top = general.topRpcs
			.concat(interactions.topRpcs)
			.map((r) => `${r.rpc}=${r.allowed}${r.blocked > 0 ? `/-${r.blocked}` : ""}`)
			.join(" ");
		logger.info(
			LogType.GRPC,
			`[carga] ${allowed} admitidas, ${blocked} rechazadas por límite · en vuelo ${inFlight.total} (máx ${inFlight.max} de ${inFlight.trackers} servicios) · pico concurrencia/módulo ${concurrencyPeak}${top ? ` · top ${top}` : ""}`
		);

		// `blocked > 0` significa que un módulo ha tocado su techo: eso no es carga
		// normal, es un módulo desbocado o un límite mal calibrado. Sube a warn para
		// que se vea sin tener que leer la línea de arriba.
		if (blocked > 0) {
			logger.warn(LogType.GRPC, `[carga] ${blocked} peticiones rechazadas por límite de tasa en el último minuto`);
		}
		// Y esto es más grave todavía: un módulo con 256 peticiones vivas a la vez es
		// el patrón exacto del incidente del 11-08. Si esto salta, hay que mirar qué
		// módulo antes de que se lleve por delante a los otros nueve.
		if (concurrencyRejected > 0) {
			logger.warn(
				LogType.GRPC,
				`[carga] ${concurrencyRejected} peticiones rechazadas por TECHO DE CONCURRENCIA (${MAX_IN_FLIGHT_PER_MODULE} por módulo) en el último minuto`
			);
		}
	}, 60_000).unref();

	const commandsStore = new CommandsStore();
	// Reconciliador de comandos, sólo en el master: recoge los cambios de
	// `allowed_modules` que no disparan ningún `reloadCommands` (el PATCH del
	// panel sólo escribe en Mongo) y reintenta un PUT que falló. Ver
	// `SlashCommandStore.startDriftReconciler`.
	commandsStore.slashCommands.startDriftReconciler();
	const slashCommandService = new SlashCommandGrpcService(commandsStore);

	clusterIPC.setMessageResponseHandler((id, resp) => messageService.handleWorkerResponse(id, resp));
	clusterIPC.setUserResponseHandler((id, resp) => userService.handleWorkerResponse(id, resp));
	clusterIPC.setMemberResponseHandler((id, resp) => memberService.handleWorkerResponse(id, resp));
	clusterIPC.setGuildResponseHandler((id, resp) => guildService.handleWorkerResponse(id, resp));
	clusterIPC.setChannelResponseHandler((id, resp) => channelService.handleWorkerResponse(id, resp));
	clusterIPC.setThreadResponseHandler((id, resp) => threadService.handleWorkerResponse(id, resp));
	clusterIPC.setRoleResponseHandler((id, resp) => roleService.handleWorkerResponse(id, resp));
	clusterIPC.setClientResponseHandler((id, resp) => clientService.handleWorkerResponse(id, resp));
	clusterIPC.setInteractionResponseHandler((id, resp) => interactionService.handleWorkerResponse(id, resp));
	clusterIPC.setVoiceResponseHandler((id, resp) => voiceService.handleWorkerResponse(id, resp));

	// Lookup now resolved by worker directly via Redis — IPC chain removed

	const handlers: Record<string, Record<string, ServiceHandler>> = {
		message: adaptImpl(messageService.getImplementation() as any),
		user: adaptImpl(userService.getImplementation() as any),
		interaction: adaptImpl(interactionService.getImplementation() as any),
		member: adaptImpl(memberService.getImplementation() as any),
		guild: adaptImpl(guildService.getImplementation() as any),
		channel: adaptImpl(channelService.getImplementation() as any),
		thread: adaptImpl(threadService.getImplementation() as any),
		role: adaptImpl(roleService.getImplementation() as any),
		client: adaptImpl(clientService.getImplementation() as any),
		slashCommand: adaptImpl(slashCommandService.getImplementation() as any),
		voice: adaptImpl(voiceService.getImplementation() as any),
		cluster: adaptImpl(clusterService.getImplementation() as any)
	};

	const address = `${env.grpc.host}:${env.grpc.port}`;
	const credentials = grpc.credentials.createInsecure();
	// Audit 5.2: TCP keepalive on the client channel. Without it, a
	// half-open TCP connection (network blip, NAT timeout, remote
	// host gone) doesn't surface as a write error until the OS gives
	// up — typically minutes. The @grpc/grpc-js keepalive options
	// are passed at the channel level: the OS sends TCP keepalives
	// every `keepalive_time_ms`, and the connection is considered
	// dead if no ack comes back within `keepalive_timeout_ms`. The
	// scheduler's reconnect kicks in within 30s of detecting the
	// failure, well below the previous "minutes of stale traffic"
	// window. The SDK side (`library/sdk`) already configures
	// `grpc.keepalive_time_ms`; this closes the core-side gap.
	//
	// Audit 5.6.8: 16MB receive / send message cap. The default
	// in @grpc/grpc-js is 4MB which silently truncates channel
	// topic lists, member dumps for huge guilds, and bulk
	// interactions. 16MB is enough for any realistic Discord
	// payload (largest possible: ~5MB for a 500-channel guild
	// metadata dump) while still bounding the per-message heap
	// allocation. Anything larger than 16MB is almost certainly
	// a misuse (paste of a base64-encoded image into a custom_id,
	// etc.) and should be rejected explicitly with
	// RESOURCE_EXHAUSTED instead of becoming an OOM crash.
	const MAX_GRPC_MESSAGE_BYTES = 16 * 1024 * 1024;
	const grpcChannelOptions = {
		"grpc-node.flow_control_window": 8 * 1024 * 1024,
		"grpc.keepalive_time_ms": 30_000,
		"grpc.keepalive_timeout_ms": 10_000,
		"grpc.keepalive_permit_without_calls": 1,
		"grpc.max_receive_message_length": MAX_GRPC_MESSAGE_BYTES,
		"grpc.max_send_message_length": MAX_GRPC_MESSAGE_BYTES
	};

	const registryClient = new GrpcRegistryClient(address, credentials, grpcChannelOptions);
	const channelClient = new GrpcCoreChannelClient(address, credentials, grpcChannelOptions);
	const botId = env.bot.id;
	const connection_key = env.grpc.connectionKey;
	const protocol_version = env.grpc.protocolVersion ?? "1";
	let registryHeartbeatTimer: NodeJS.Timeout | null = null;

	// Single-source-of-truth for the live work channel. We must destroy AND
	// remove all listeners on the previous stream before opening a new one,
	// otherwise leftover `data` / `error` / `end` handlers keep the old stream
	// object (and its closure-captured `handlers` graph + heartbeat timer)
	// retained in memory across every reconnect cycle. Under a flaky gateway
	// during boot this accumulates fast.
	let currentStream: ReturnType<typeof channelClient.workChannel> | null = null;
	let currentHeartbeatTimer: NodeJS.Timeout | null = null;
	// Both `error` and `end` can fire on the same stream teardown. Without a
	// guard we schedule two reconnects → two openWorkChannel calls → two live
	// streams (until the next failure tears one down). One-shot per cycle.
	let reconnectScheduled = false;
	// Backoff counter for `scheduleReconnect`. Doubled each failed
	// reconnect (5s → 10s → 20s → ... → 120s cap). Se resetea cuando el stream
	// demuestra estabilidad, no al abrirlo — ver `STREAM_STABLE_MS`.
	let reconnectAttempts = 0;

	/**
	 * Siguiente retardo de reconexión, con jitter, y consume un intento.
	 *
	 * Antes eran dos copias literales del mismo cálculo (aquí y en el camino de
	 * `registerCore` fallido) que ya habían empezado a divergir. El jitter es lo
	 * nuevo: sin él, N bots que pierden la gateway a la vez reintentan todos en
	 * el mismo instante contra un peer recién arrancado. Es "equal jitter"
	 * (mitad fija + mitad aleatoria), así que nunca supera el tope de 120s.
	 */
	function nextBackoffMs(): number {
		const capped = Math.min(5_000 * 2 ** reconnectAttempts, 120_000);
		reconnectAttempts++;
		return Math.round(capped * (0.5 + Math.random() * 0.5));
	}

	function teardownStream(): void {
		if (currentHeartbeatTimer) {
			clearInterval(currentHeartbeatTimer);
			currentHeartbeatTimer = null;
		}
		// The registry-side heartbeat was orphaned across teardowns: it kept
		// pinging the gateway with a `bot_id` whose work channel had been
		// torn down. After a gateway restart the gateway's in-memory
		// registry was empty, so every heartbeat got `ack.ok=false reason
		// "Unknown core id"` which the no-op callback below silently
		// discarded — the core appeared healthy from its own logs while the
		// gateway saw it as missing. Tear it down so the next `connect()`
		// recreates a fresh one tied to the new registration.
		if (registryHeartbeatTimer) {
			clearInterval(registryHeartbeatTimer);
			registryHeartbeatTimer = null;
		}
		if (currentStream) {
			const dying = currentStream;
			// `removeAllListeners` BEFORE `destroy` — `destroy()` itself can
			// synchronously emit one final `error`, and we don't want the old
			// handler firing a third reconnect schedule.
			dying.removeAllListeners();
			// ...but a stream with NO `error` listener is a loaded gun: Node
			// rethrows an unhandled `error` event out of `emit`, and grpc-js
			// delivers the RST_STREAM/GOAWAY of a gateway restart a tick or
			// more AFTER we tear down — outside the try/catch below. That
			// escaped as an uncaughtException, and since the master treats a
			// non-transient uncaught error as fatal (and PM2 runs the core with
			// autorestart:false), restarting the gateway took every bot down
			// for good. Re-arm a no-op sink that outlives the teardown.
			dying.on("error", (err: Error) => {
				logger.debug(LogType.GRPC, `Work channel error after teardown (ignored): ${err.message}`);
			});
			if (!dying.destroyed) {
				try {
					dying.destroy();
				} catch {
					// destroy() on an already-closing duplex is a no-op but can
					// throw in older grpc-js versions; swallow.
				}
			}
			currentStream = null;
		}
	}

	function scheduleReconnect(): void {
		if (reconnectScheduled) return;
		reconnectScheduled = true;
		teardownStream();
		// Exponential backoff capped at 120s. Without this, a multi-minute
		// gateway outage floods the log with one reconnect attempt every 5s
		// (180 lines/min × N bots).
		const backoffMs = nextBackoffMs();
		setTimeout(() => {
			reconnectScheduled = false;
			connect();
		}, backoffMs);
	}

	function openWorkChannel(heartbeat_interval_ms: number): void {
		// Defensive: if a previous stream is still around (e.g. registry
		// reconnect raced with a stream error), tear it down before opening.
		teardownStream();

		const meta = new grpc.Metadata();
		meta.set("x-bot-id", botId);
		const stream = channelClient.workChannel(meta);
		currentStream = stream;

		// Delivery guarantee on this work channel is AT-MOST-ONCE: each gateway
		// request is handled once and the response is written back on the same
		// stream. If the stream dies before the response lands, drainPending
		// rejects every in-flight request with UNAVAILABLE — there is NO replay
		// of the original request. Callers must treat a failed work-channel RPC
		// as "may or may not have executed" and not assume retry-on-the-wire.
		//
		// Backpressure collapse detector. `stream.write()` returning false means
		// the send buffer is full; the response is queued, not lost — but a
		// gateway that never drains keeps the request "in flight" until it times
		// out silently. Count consecutive false writes and, past the threshold,
		// treat the stream as collapsed and force a fresh one via the same
		// reconnect path used on error/end. A single true write resets it.
		let consecutiveBackpressuredWrites = 0;
		const BACKPRESSURE_COLLAPSE_THRESHOLD = 10;

		/**
		 * Write to the work channel without ever letting the failure escape.
		 *
		 * `stream.destroyed` alone is not enough: between the gateway sending
		 * its GOAWAY and grpc-js destroying the duplex, the stream is ended but
		 * NOT destroyed, and a write in that window throws
		 * ERR_STREAM_WRITE_AFTER_END. From the heartbeat timer that throw is an
		 * uncaughtException; from the async `data` handler it is an
		 * unhandledRejection. Either one is fatal to the master (see the
		 * handlers in cluster/master/index.ts), which is exactly how a gateway
		 * restart used to take the bots down.
		 *
		 * Returns `true` when the write was accepted, `false` when it was
		 * buffered (backpressure), `null` when the stream was already gone.
		 */
		function safeWrite(msg: GrpcCoreResponse): boolean | null {
			if (stream.destroyed || stream.writableEnded) return null;
			try {
				return stream.write(msg);
			} catch (err) {
				logger.warn(
					LogType.GRPC,
					`Work channel write failed (${err instanceof Error ? err.message : String(err)}) — reconnecting`
				);
				scheduleReconnect();
				return null;
			}
		}

		stream.on("data", async (req: GrpcCoreRequest) => {
			if (req.request_id === "") return;

			// Structured args (service/method/requestId) instead of a
			// template string. Pino skips the metadata object when debug
			// is disabled, removing string-concat cost from the gRPC hot
			// path. Plain `[Core recv]` survives as a stable grep token.
			logger.debug(LogType.GRPC, "[Core recv]", {
				service: req.service,
				method: req.method,
				request_id: req.request_id
			});

			const serviceHandlers = handlers[req.service];
			const handler = serviceHandlers?.[req.method];

			if (!handler) {
				logger.warn(LogType.GRPC, `[Core recv] No handler for ${req.service}.${req.method}`);
				safeWrite({
					request_id: req.request_id,
					ok: false,
					payload: "",
					grpc_status: grpc.status.NOT_FOUND,
					error_message: `Unknown handler: ${req.service}.${req.method}`
				});
				return;
			}

			if (req.source_module_id !== "") {
				const allowed = await getBotAllowedModules(botId);
				if (allowed.length > 0 && !allowed.includes(req.source_module_id)) {
					logger.warn(LogType.GRPC, "[Core recv] Module denied by bot scope", {
						bot_id: botId,
						source_module_id: req.source_module_id,
						service: req.service,
						method: req.method,
						request_id: req.request_id
					});
					safeWrite({
						request_id: req.request_id,
						ok: false,
						payload: "",
						grpc_status: grpc.status.PERMISSION_DENIED,
						error_message: `Module "${req.source_module_id}" is not allowed for this bot`
					});
					return;
				}
			}

			try {
				const request = JSON.parse(req.payload, (_key, value) => {
					if (value !== null && typeof value === "object" && typeof value.__b64__ === "string") {
						return Buffer.from(value.__b64__, "base64");
					}
					return value;
				});
				const result = await handler(request);
				const ok = safeWrite({
					request_id: req.request_id,
					ok: true,
					payload: JSON.stringify(result),
					grpc_status: 0,
					error_message: ""
				});
				// `null` = the stream was already gone; safeWrite has scheduled
				// the reconnect, and this response is lost by design (the work
				// channel is at-most-once).
				if (ok !== null) {
					if (ok) {
						consecutiveBackpressuredWrites = 0;
					} else {
						consecutiveBackpressuredWrites++;
						logger.warn(LogType.GRPC, "[backpressure] core→gateway buffer full", {
							service: req.service,
							method: req.method,
							consecutive: consecutiveBackpressuredWrites
						});
						if (consecutiveBackpressuredWrites >= BACKPRESSURE_COLLAPSE_THRESHOLD) {
							// Gateway isn't draining — the stream is effectively
							// dead. Force a fresh one so in-flight requests fail
							// fast (drainPending → UNAVAILABLE) instead of timing
							// out silently one by one.
							logger.error(
								LogType.GRPC,
								`[backpressure] ${consecutiveBackpressuredWrites} consecutive full writes — stream collapsed, reconnecting`
							);
							scheduleReconnect();
						}
					}
				}
			} catch (err: any) {
				logger.error(
					LogType.GRPC,
					`[Core handler error] ${req.service}.${req.method}: ${err.message ?? String(err)}`
				);
				if (!(err instanceof KenaCoreError)) {
					reportError(err, {
						layer: "grpc",
						operation: `${req.service}.${req.method}`,
						source: "INTERNAL",
						extra: { request_id: req.request_id }
					});
				}
				if (err instanceof KenaCoreError) {
					safeWrite({
						request_id: req.request_id,
						ok: true,
						payload: JSON.stringify(ResponseBuilder.error(err.responseCode, err.message, {})),
						grpc_status: 0,
						error_message: ""
					});
				} else {
					safeWrite({
						request_id: req.request_id,
						ok: false,
						payload: "",
						grpc_status: err.code ?? grpc.status.INTERNAL,
						error_message: err.message ?? "Internal error"
					});
				}
			}
		});

		stream.on("error", (err) => {
			logger.warn(LogType.GRPC, `Work channel error: ${err.message}`);
			reportError(err, { layer: "grpc", operation: "workChannel.stream", source: "INTERNAL" });
			scheduleReconnect();
		});

		stream.on("end", () => {
			logger.warn(LogType.GRPC, "Work channel closed by gateway — reconnecting in 5s");
			scheduleReconnect();
		});

		const heartbeat: GrpcCoreResponse = {
			request_id: "",
			ok: true,
			payload: "",
			grpc_status: 0,
			error_message: ""
		};
		currentHeartbeatTimer = setInterval(() => {
			safeWrite(heartbeat);
		}, heartbeat_interval_ms);

		if (!registryHeartbeatTimer) {
			registryHeartbeatTimer = setInterval(() => {
				// Audit 5.2: deadline on the heartbeat. The OLD code's
				// callback never fired if the gateway silently died —
				// a half-open TCP socket. The keepalive on the channel
				// (set above) detects the dead socket within ~40s; this
				// deadline is the belt-and-braces: if the gateway is
				// alive but stalled (event loop wedged) the deadline
				// surfaces the error and the callback's `err` branch
				// triggers the reconnect.
				const heartbeatDeadlineMs = heartbeat_interval_ms - 1_000;
				const deadlineTimer = setTimeout(() => {
					logger.warn(
						LogType.GRPC,
						`coreHeartbeat deadline exceeded (${heartbeatDeadlineMs}ms) — forcing reconnect`
					);
					scheduleReconnect();
				}, heartbeatDeadlineMs);
				registryClient.coreHeartbeat({ id: botId, metrics: getMetrics() }, (err, ack) => {
					clearTimeout(deadlineTimer);
					// Silent-discarding this callback was the original sin: a
					// gateway restart wipes its in-memory registry, so every
					// heartbeat returns `ok:false reason "Unknown core id"` and
					// the core never re-registers because nothing triggers
					// `connect()`. Tear the stream down so the existing
					// reconnect path kicks in and re-registers.
					if (err) {
						logger.warn(LogType.GRPC, `coreHeartbeat error: ${err.message} — forcing reconnect`);
						scheduleReconnect();
						return;
					}
					if (ack && !ack.ok) {
						logger.warn(
							LogType.GRPC,
							`coreHeartbeat rejected by gateway: ${ack.reason || "unknown"} — forcing reconnect`
						);
						scheduleReconnect();
					}
				});
			}, heartbeat_interval_ms);
		}

		logger.info(LogType.GRPC, `Work channel open (heartbeat every ${heartbeat_interval_ms}ms)`);

		// El backoff se resetea por ESTABILIDAD, no por haber creado el objeto.
		// `channelClient.workChannel()` devuelve el duplex de forma síncrona, sin
		// esperar al servidor: resetear aquí mismo (que es lo que se hacía)
		// significaba que cualquier fallo posterior —rechazo del gateway, deadline
		// del heartbeat, colapso por backpressure— volvía a empezar en 5s. El
		// resultado era un ciclo fijo de 5s indefinido, justo lo que el backoff
		// venía a evitar.
		//
		// El guard `currentStream === stream` hace que un stream ya reemplazado no
		// pueda resetear el contador del que le sucedió.
		const stableTimer = setTimeout(() => {
			if (currentStream !== stream) return;
			if (reconnectAttempts === 0) return;
			logger.debug(LogType.GRPC, `Work channel estable ${STREAM_STABLE_MS}ms — backoff reiniciado`);
			reconnectAttempts = 0;
		}, STREAM_STABLE_MS);
		// Vigilar la estabilidad no debe mantener vivo el proceso.
		stableTimer.unref();
	}

	function connect(): void {
		registryClient.registerCore(
			{
				connection_key,
				bot_id: botId,
				host: "",
				port: 0,
				protocol_version,
				metrics: getMetrics()
			},
			new grpc.Metadata(),
			// Sin deadline, un gateway que acepta el TCP pero cuyo handler nunca
			// responde dejaba este callback sin invocar para siempre — y con él,
			// todo el enlace muerto sin nadie que lo reintentase.
			{ deadline: Date.now() + REGISTER_CORE_DEADLINE_MS },
			(err, ack) => {
				if (err || !ack?.accepted) {
					// Mismo backoff (con jitter) que `scheduleReconnect`, para que
					// un gateway caído no genere una línea de log cada 5s.
					const backoffMs = nextBackoffMs();
					logger.error(
						LogType.GRPC,
						`Core registration failed: ${err?.message ?? ack?.reason} — retrying in ${Math.round(backoffMs / 1000)}s`
					);
					reportError(err ?? new Error(ack?.reason ?? "Core registration rejected"), {
						layer: "lifecycle",
						operation: "registerCore",
						source: "INTERNAL",
						extra: { bot_id: botId, reason: ack?.reason }
					});
					setTimeout(connect, backoffMs);
					return;
				}
				logger.info(LogType.GRPC, `Core registered with gateway (heartbeat=${ack.heartbeat_interval_ms}ms)`);
				openWorkChannel(Math.max(1_000, ack.heartbeat_interval_ms || 5_000));
			}
		);
	}

	// waitForReady se llamaba una sola vez al boot. Si el gateway estaba
	// caído (>30s), el callback simplemente retornaba y la registración
	// nunca se intentaba de nuevo — el core quedaba en estado degradado
	// para siempre. Lo reemplazamos por un loop de reintentos con backoff
	// exponencial (15s → 30s → 60s cap) que termina solo cuando el
	// handshake inicial se completa.
	function waitForGatewayAndConnect(attempt = 1): void {
		const deadline = Date.now() + 30_000;
		registryClient.waitForReady(deadline, (err) => {
			if (err) {
				const backoff = Math.min(15_000 * 2 ** Math.min(attempt - 1, 2), 60_000);
				logger.error(
					LogType.GRPC,
					`Gateway not reachable: ${err.message} — retrying in ${backoff}ms (attempt ${attempt})`
				);
				reportError(err, { layer: "lifecycle", operation: "waitForReady", source: "INTERNAL" });
				setTimeout(() => waitForGatewayAndConnect(attempt + 1), backoff);
				return;
			}
			connect();
		});
	}
	waitForGatewayAndConnect();

	process.on("SIGUSR2", () => {
		logger.info(LogType.GRPC, "Signal SIGUSR2 — core is running as gateway client");
	});
}

