39	
40	export class RequestTracker {
41		private readonly pendingRequests = new Map<string, PendingRequest>();
42		/**
43		 * Audit 1.6: a small ring of late-arriving success responses for
44		 * requests that already timed out. We keep them around for a brief
45		 * window so the caller (InteractionGrpcService) can convert a
46		 * tracker-induced DEFER_TIMEOUT into a real success when the worker's
47		 * POST actually completed before Discord rejected anything.
48		 */
49		private readonly lateSuccesses = new Map<string, MessageResponseIPC>();
50		/**
51		 * Bounded so the ring can't grow under a sustained stream of late
52		 * successes. 256 is a comfortable upper bound for the rate at which
53		 * a worker might legitimately be late (we keep the most recent 256).
54		 */
55		private static readonly LATE_SUCCESS_MAX = 256;
56		/**
57		 * Tope duro de `pendingRequests`. Sin él, cada entrada retiene su closure
58		 * resolve/reject, un `Timeout` y —porque el llamante queda suspendido en
59		 * `await` hasta que la promesa se asiente— el payload completo de la
60		 * petición (hasta 16 MiB por `grpc.max_receive_message_length`,
61		 * infrastructure/grpc/server.ts) vivo en el cierre, mientras se espera al
62		 * worker. Si las peticiones entran más rápido de lo que el worker
63		 * resuelve, el Map crecería hasta donde aguante el heap — es lo que
64		 * mejor explica los 10 GB del 11-08-2026 (docs/AUDITORIA-limites-grpc-2026-08-11.md).
65		 *
66		 * 5000 queda muy por encima del peor caso ya cubierto por el techo de
67		 * concurrencia por módulo (GrpcRateLimiter.maxInFlightPerModule=256 ×
68		 * hasta ~10 módulos ≈ 2560, infrastructure/grpc/server.ts), así que no
69		 * debería activarse nunca con ese límite en pie — es el backstop para
70		 * cuando falta (servicios sin rate limiter) o falla.
71		 */
72		private static readonly DEFAULT_MAX_PENDING = 5000;
73		private readonly maxPending: number;
74		/** Peticiones rechazadas de entrada por tocar `maxPending`, para poder medirlo. */
75		private rejectedByCapacity = 0;
76		private readonly defaultTimeout: number;
77		private onSettle?: (request_id: string) => void;
78		private onLateSuccess?: (request_id: string, response: MessageResponseIPC) => void;
79	
80		constructor(defaultTimeout = 30000, maxPending = RequestTracker.DEFAULT_MAX_PENDING) {
81			// 30 seconds default
82			this.defaultTimeout = defaultTimeout;
83			this.maxPending = maxPending;
84			// Se apunta al registro para que la profundidad de la cola sea medible sin
85			// abrir un getter en cada servicio. Los trackers viven lo que el proceso, así
86			// que no hace falta darse de baja.
87			liveTrackers.add(this);
88		}
89	
90		/**
91		 * Register a callback fired whenever a request is fully settled (resolve,
92		 * reject, timeout, or supersede). Used by ClusterIPC to clear its
93		 * `pendingByCluster` rejector so a later cluster-exit doesn't try to
94		 * invoke a no-op `rejectRequest` and spam "Cannot reject unknown
95		 * request" warnings.
96		 */
97		setOnSettle(cb: (request_id: string) => void): void {
98			this.onSettle = cb;
99		}
100	
101		/**
102		 * Audit 1.6: register a callback fired when a success response arrives
103		 * for a request that has already timed out. The InteractionGrpcService
104		 * uses this to convert a tracker-induced DEFER_TIMEOUT into OK so the
105		 * SDK doesn't set deferFailed=true on a defer that actually succeeded.
106		 */
107		setOnLateSuccess(cb: (request_id: string, response: MessageResponseIPC) => void): void {
108			this.onLateSuccess = cb;
109		}
110	
111		/**
112		 * Track a request and return a promise that resolves when the response arrives
113		 */
114		trackRequest(request_id: string, timeoutMs?: number): Promise<MessageResponseIPC> {
115			// Collision: reject the previous holder immediately and clear its
116			// timer before installing the new one. Without this, the prior
117			// promise would leak until its 30s timer fires AND its expiry would
118			// delete the NEW entry — making the new caller's response land as
119			// "Received response for unknown request" and itself time out.
120			const prior = this.pendingRequests.get(request_id);
121			if (prior) {
122				clearTimeout(prior.timeout);
123				this.pendingRequests.delete(request_id);
124				prior.reject(new Error(`Request ${request_id} superseded by a new tracker entry (trace_id collision)`));
125				this.onSettle?.(request_id);
126				logger.warn(LogType.CLUSTER, `Request ${request_id} was already tracked — rejected the prior promise`);
127			}
128	
129			if (this.pendingRequests.size >= this.maxPending) {
130				this.rejectedByCapacity++;
131				logger.warn(
132					LogType.CLUSTER,
133					`Request ${request_id} rejected: tracker at capacity (${this.pendingRequests.size}/${this.maxPending} pending)`
134				);
135				return Promise.reject(
136					new Error(`Request ${request_id} rejected: too many pending requests (max ${this.maxPending})`)
137				);
138			}
139	
140			return new Promise<MessageResponseIPC>((resolve, reject) => {
141				const timeout = setTimeout(() => {
142					this.pendingRequests.delete(request_id);
143					this.onSettle?.(request_id);
144					reject(new Error(`Request ${request_id} timed out after ${timeoutMs || this.defaultTimeout}ms`));
145				}, timeoutMs || this.defaultTimeout);
146	
147				this.pendingRequests.set(request_id, {
148					resolve,
149					reject,
150					timeout,
151					timestamp: Date.now()
152				});
153	
154				logger.info(
155					LogType.CLUSTER,
156					`Tracking request ${request_id} with timeout ${timeoutMs || this.defaultTimeout}ms`
157				);
158			});
159		}
160	
161		/**
162		 * Resolve a tracked request with a response
163		 */
164		resolveRequest(request_id: string, response: MessageResponseIPC): boolean {
165			const pending = this.pendingRequests.get(request_id);
166			if (!pending) {
167				// Audit 1.6: a success response arriving AFTER the tracker
168				// timed out used to be dropped silently. We now keep a
169				// bounded ring of late successes and fire the onLateSuccess
170				// hook so the caller can convert the timeout into OK. A
171				// failure response is still discarded — letting late
172				// failures slip through would let a real defer failure
173				// masquerade as a late success.
174				if (response?.success) {
175					this.recordLateSuccess(request_id, response);
176					logger.warn(LogType.CLUSTER, `[late_success] received success for already-settled request ${request_id}`);
177					this.onLateSuccess?.(request_id, response);
178				} else {
179					logger.warn(LogType.CLUSTER, `Received response for unknown request ${request_id}`);
180				}
181				return false;
182			}
183	
184			clearTimeout(pending.timeout);
185			this.pendingRequests.delete(request_id);
186			this.onSettle?.(request_id);
187	
188			const duration = Date.now() - pending.timestamp;
189			logger.info(LogType.CLUSTER, `Request ${request_id} resolved in ${duration}ms`);
190	
191			pending.resolve(response);
192			return true;
193		}
194	
195		/**
196		 * Audit 1.6: bounded ring of late-arriving success responses. The
197		 * oldest entry is evicted FIFO when the cap is hit so a sustained
198		 * stream of late successes can't grow the Map without bound.
199		 */
200		private recordLateSuccess(request_id: string, response: MessageResponseIPC): void {
201			if (this.lateSuccesses.size >= RequestTracker.LATE_SUCCESS_MAX) {
202				const oldest = this.lateSuccesses.keys().next().value;
203				if (oldest !== undefined) this.lateSuccesses.delete(oldest);
204			}
205			this.lateSuccesses.set(request_id, response);
206		}
207	
208		/**
209		 * Audit 1.6: lookup (and clear) a late success. The InteractionGrpcService
210		 * calls this from its catch block after a tracker-timeout to check
211		 * whether the worker actually completed the defer despite the timer.
212		 */
213		consumeLateSuccess(request_id: string): MessageResponseIPC | null {
214			const response = this.lateSuccesses.get(request_id);
215			if (response) this.lateSuccesses.delete(request_id);
216			return response ?? null;
217		}
218	
219		/**
220		 * Reject a tracked request with an error
221		 */
222		rejectRequest(request_id: string, error: Error): boolean {
223			const pending = this.pendingRequests.get(request_id);
224			if (!pending) {
225				logger.warn(LogType.CLUSTER, `Cannot reject unknown request ${request_id}`);
226				return false;
227			}
228	
229			clearTimeout(pending.timeout);
230			this.pendingRequests.delete(request_id);
231			this.onSettle?.(request_id);
232	
233			logger.error(LogType.CLUSTER, `Request ${request_id} rejected:`, error);
234	
235			pending.reject(error);
236			return true;
237		}
238	
239		/**
240		 * Get the number of pending requests
241		 */
242		getPendingCount(): number {
243			return this.pendingRequests.size;
244		}
245	
246		/**
247		 * Peticiones rechazadas de entrada desde el arranque por tocar `maxPending`.
248		 */
249		getRejectedCount(): number {
250			return this.rejectedByCapacity;
251		}
252	
253		/**
254		 * Clear all pending requests (useful for testing or shutdown)
255		 */
256		clearAll(): void {
257			for (const pending of this.pendingRequests.values()) {
258				clearTimeout(pending.timeout);
259				pending.reject(new Error("Request tracker cleared"));
260			}
261			this.pendingRequests.clear();
262			this.lateSuccesses.clear();
263			logger.info(LogType.CLUSTER, "All pending requests cleared");
264		}
265	}
