it("defaults to a ceiling high enough that normal traffic never hits it", async () => {
	tracker = new RequestTracker(30000);
	const pending = Array.from({ length: 100 }, (_, i) => tracker.trackRequest(`trace-${i}`, 60000));
	expect(tracker.getPendingCount()).toBe(100);
	expect(tracker.getRejectedCount()).toBe(0);

	// clearAll() rejects every one of them — attach handlers first so none
	// surfaces as an unhandled rejection.
	const settled = Promise.allSettled(pending);
	tracker.clearAll();
	await settled;
});

it("pendingRequestsSnapshot aggregates rejections across trackers", async () => {
	const other = new RequestTracker(30000, 1);
	tracker = new RequestTracker(30000, 1);

	const p1 = tracker.trackRequest("trace-1", 60000);
	const p2 = other.trackRequest("trace-2", 60000);

	await expect(tracker.trackRequest("trace-3", 60000)).rejects.toThrow();
	await expect(other.trackRequest("trace-4", 60000)).rejects.toThrow();

	const snapshot = pendingRequestsSnapshot();
	expect(snapshot.rejected).toBeGreaterThanOrEqual(2);

	const settled = Promise.allSettled([p1, p2]);
	tracker.clearAll();
	other.clearAll();
	await settled;
});

