// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker, pendingRequestsSnapshot } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * RAM hole #2 from docs/AUDITORIA-limites-grpc-2026-08-11.md: `pendingRequests`
 * had no `maxPending`, so a worker resolving slower than requests arrive grew
 * the map (closures + Timeout + payload per entry) without bound. These tests
 * pin the fix: a hard ceiling that rejects new requests once the tracker is
 * saturated instead of accepting them and growing forever.
 */
describe("RequestTracker — maxPending ceiling", () => {
	let tracker: RequestTracker;

	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects a new request once the tracker is at capacity, without growing pendingRequests", async () => {
		tracker = new RequestTracker(30000, 2);

		// Fill the tracker to its cap. Both stay pending (no timers fired).
		const p1 = tracker.trackRequest("trace-1", 60000);
		const p2 = tracker.trackRequest("trace-2", 60000);
		expect(tracker.getPendingCount()).toBe(2);

		// A third request arrives while the tracker is saturated: rejected
		// immediately, no entry added.
		await expect(tracker.trackRequest("trace-3", 60000)).rejects.toThrow(/too many pending requests/);
		expect(tracker.getPendingCount()).toBe(2);
		expect(tracker.getRejectedCount()).toBe(1);

		// The two original requests are unaffected — resolving them frees room.
		tracker.resolveRequest("trace-1", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as any);
		await expect(p1).resolves.toMatchObject({ success: true });

		expect(tracker.getPendingCount()).toBe(1);
		const p3 = tracker.trackRequest("trace-4", 60000);
		expect(tracker.getPendingCount()).toBe(2);

		// Cleanup: settle the rest so no fake timer stays dangling.
		tracker.rejectRequest("trace-2", new Error("cleanup"));
		tracker.rejectRequest("trace-4", new Error("cleanup"));
		await expect(p2).rejects.toThrow("cleanup");
		await expect(p3).rejects.toThrow("cleanup");
	});

	it("a trace_id collision frees a slot before the capacity check runs", async () => {
		tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("trace-1", 60000);
		// Same id again: this supersedes (and rejects) the prior entry, so the
		// tracker never actually exceeds its cap of 1.
		const p2 = tracker.trackRequest("trace-1", 60000);

		await expect(p1).rejects.toThrow(/superseded/);
		expect(tracker.getPendingCount()).toBe(1);
		expect(tracker.getRejectedCount()).toBe(0);

		tracker.rejectRequest("trace-1", new Error("cleanup"));
		await expect(p2).rejects.toThrow("cleanup");
	});

	it("defaults to a ceiling high enough that normal traffic never hits it", async () => {
		tracker = new RequestTracker(30000);
		const pending = Array.from({ length: 100 }, (_, i) => tracker.trackRequest(`trace-${i}`, 60000));
		expect(tracker.getPendingCount()).toBe(100);
		expect(tracker.getRejectedCount()).toBe(0);

		// clearAll() rejects every one of them — attach handlers first so none
		// surfaces as an unhandled rejection.
		const settled = Promise.allSettled(pending);
		tracker.clearAll();
		await settled;
	});

	it("pendingRequestsSnapshot aggregates rejections across trackers", async () => {
		const other = new RequestTracker(30000, 1);
		tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("trace-1", 60000);
		const p2 = other.trackRequest("trace-2", 60000);

		await expect(tracker.trackRequest("trace-3", 60000)).rejects.toThrow();
		await expect(other.trackRequest("trace-4", 60000)).rejects.toThrow();

		const snapshot = pendingRequestsSnapshot();
		expect(snapshot.rejected).toBeGreaterThanOrEqual(2);

		const settled = Promise.allSettled([p1, p2]);
		tracker.clearAll();
		other.clearAll();
		await settled;
	});
});
